122|/***
123| * MARK: selectStagePresentation
124| * @description Single source of truth for how the current-stage row presents:
125| *   settled tasks never render a live ticking row — a parked failure shows a
126| *   static PARKED label — while only genuinely executing tasks tick. A
127| *   settled `failed` merge task is parked (needs operator retry), not
128| *   active: rendering it ACTIVE with a growing "Nm in stage" timer is what
129| *   made parked merge failures look stuck. The settled verdicts share one
130| *   vocabulary (`isTaskSettledStatus`) with the RETRYING read, so a status
131| *   can never be "live" for one and "settled" for the other. Unknown or
132| *   missing statuses read ACTIVE (fail open: a task that cannot be proven
133| *   settled must never look parked).
134| * @example selectStagePresentation({ status: 'failed' }) => { label: 'PARKED', tone: 'parked', ticking: false }
135| * @example selectStagePresentation({ status: 'paused' }) => { label: 'PAUSED', tone: 'parked', ticking: false }
136| * @example selectStagePresentation({ status: 'in_stage' }) => { label: 'ACTIVE', tone: 'active', ticking: true }
137| * @param {Object} [task] - The task object (or null/undefined for safety).
138| * @returns {{ label: string, tone: string, ticking: boolean }} Presentation verdict.
139| ***/
140|export function selectStagePresentation(task) {
141|  const status = typeof task?.status === 'string' ? task.status.trim().toLowerCase() : '';
142|  if (status === 'completed' || status === 'done') {
143|    return { label: 'DONE', tone: 'done', ticking: false };
144|  }
145|  if (status === 'waiting_human' || status === 'waiting-human' || status === 'waiting') {
146|    return { label: 'WAITING', tone: 'waiting', ticking: false };
147|  }
148|  if (isTaskSettledStatus(task)) {
149|    // Paused keeps its own label so the row names the operator action that
