151|    // cancelled, aborted) parks generically. None of them tick.
152|    if (status === 'paused') {
153|      return { label: 'PAUSED', tone: 'parked', ticking: false };
154|    }
155|    return { label: 'PARKED', tone: 'parked', ticking: false };
156|  }
157|  return { label: 'ACTIVE', tone: 'active', ticking: true };
158|}
