113|/***
114| * MARK: countInterrupted
115| * @description Counts tasks still carrying the `interrupted` label. Used for
116| *   the startup log line ("N interrupted → M auto-resumed").
117| * @param {Object} store
118| * @returns {number}
119| ***/
120|export function countInterrupted(store) {
121|	if (
122|		!store.projectStore ||
123|		typeof store.projectStore.listProjects !== "function"
124|	) {
125|		return 0;
126|	}
127|	let count = 0;
128|	for (const project of store.projectStore.listProjects()) {
129|		let tasks;
130|		try {
131|			tasks = store.listTasks(project.id, project.cwd);
132|		} catch {
133|			continue;
134|		}
135|		for (const task of tasks) {
136|			if (task?.status === "interrupted") count += 1;
137|		}
138|	}
139|	return count;
140|}
