142|/***
143| * MARK: performStartupRecovery
144| * @description Establishes the initial queue after a stop, crash, or
145| *   SIGTERM/SIGINT restart, in strict order:
146| *     1. `reconcileInterruptedRuns()` — orphaned `running_*` become
147| *        `interrupted` (skipped for the live engine owner).
148| *     2. `await runInterruptionReconcilePlugins()` — installed continuity
149| *        plugins resolve their interruptions first (no-op with no plugins).
150| *        Awaited (never fire-and-forget) so no dispatch can race a
151| *        continuity decision.
152| *     3. `autoResumeInterrupted()` — eligible agent/ci/script interruptions
153| *        flip back to `in_stage`, prioritised for the queue.
154| *     4. `startScheduler()` + one `kickScheduler()` so pickup takes ~150 ms.
155| *   Recovery only transitions state: dispatch happens through the normal
156| *   `scheduleTick` under the busy gate, so the single-active invariant and
157| *   the 409 engine-busy semantics hold, and a busy engine means recovery
158| *   transitions state without dispatching. Safe to run twice: the second
159| *   pass reconciles and resumes nothing. Never rejects: every recovery step
160| *   is guarded, so the worst case is "0 auto-resumed, scheduler ticking"
161| *   rather than a failed boot.
162| * @param {Object} store
163| * @param {Object} [opts] - Passed through to `startScheduler`/`kickScheduler`
164| *   (`agentRunner`, `promptEngine`, `intervalMs`, `disabled`).
165| * @returns {Promise<Object>} `{ runs, deploys, autoResumed, interruptedFound, summary }`.
166| ***/
167|export async function performStartupRecovery(store, opts = {}) {
168|	if (!store.schedulerStats) store.schedulerStats = freshSchedulerStats();
169|
170|	// Step 0: restore the durable Tier-5 containment state BEFORE any
171|	// transition or dispatch. A restart during a systemic outage must come
172|	// back still tripped — otherwise the very first tick would re-cascade the
173|	// whole queue the breaker was protecting.
174|	try {
175|		loadCircuitState(store);
176|	} catch {
177|		// Fail open on containment: a rotted state file must never block boot.
178|	}
179|
180|	// Steps 1-3 only transition state; every one is guarded so a corrupt
181|	// project or task list degrades to "left for operator" instead of
182|	// preventing boot. Step 4 always runs: the server must leave this
183|	// function with the scheduler ticking even when recovery found nothing
184|	// (or everything failed).
185|	let runs = [];
186|	let deploys = [];
187|	let interruptedFound = 0;
188|	let autoResumed = [];
189|
190|	// 1. Orphaned live runs collapse to `interrupted` (sync, idempotent).
191|	try {
192|		runs = reconcileInterruptedRuns(store) || [];
193|	} catch {
194|		runs = [];
195|	}
196|
197|	// 2. Continuity plugins resolve their interruptions first. A failure
198|	// here must never prevent boot: the scheduler's per-tick reconcile
199|	// retries, and the tasks stay parked as `interrupted`.
200|	try {
201|		deploys = (await runInterruptionReconcilePlugins(store)) || [];
202|	} catch {
203|		deploys = [];
204|	}
205|
206|	// 3. Eligible interruptions become runnable again (no dispatch yet).
207|	try {
208|		interruptedFound = countInterrupted(store);
209|		autoResumed = autoResumeInterrupted(store) || [];
210|	} catch {
211|		interruptedFound = 0;
212|		autoResumed = [];
213|	}
214|	if (store.schedulerStats) {
215|		store.schedulerStats.resumedInterrupted =
216|			(store.schedulerStats.resumedInterrupted || 0) + autoResumed.length;
217|	}
218|
219|	// 4. Start ticking (honours `schedulerDisabled`), then shorten pickup to
220|	// one debounce instead of one full interval.
221|	startScheduler(store, opts);
222|	kickScheduler(store, opts);
223|
224|	const summary = startupRecoverySummary({ interruptedFound, autoResumed });
225|	return { runs, deploys, autoResumed, interruptedFound, summary };
226|}

