5|/***
6| * MARK: resetAttemptBudgets
7| * @description Gives a task a genuinely fresh attempt: clears every
8| *   iteration/timeout loop counter (auto-iteration count, transient
9| *   same-stage count, auto-retry flag) and restarts the stage clock, so the
10| *   failback/auto-retry budget starts over and "time in stage" measures the
11| *   new attempt only. Failure context (failureReason/lastError) is
12| *   deliberately kept: executeStage snapshots it into the next attempt's
13| *   prompt, then clears it.
14| * @example resetAttemptBudgets(task) => (counters zeroed, enteredStageAt is now)
15| * @param {Object} task
16| ***/
17|export function resetAttemptBudgets(task) {
18|	task.autoIterationCount = 0;
19|	task.autoRetrying = false;
20|	task.autoIterating = false;
21|	task.infraRetryCount = 0;
22|	task.transientRetryLadder = [];
23|	task.timeInStage = 0;
24|	task.enteredStageAt = new Date().toISOString();
25|	resetFailbackWarnings(task);
26|}

