        { stage: 'Plan', status: 'Resumed', timestamp: '2026-01-03T00:00:00.000Z' },
        { stage: 'Plan', status: 'Resumed', timestamp: '2026-01-02T00:00:00.000Z' },
        { stage: 'Plan', status: 'Moved', timestamp: '2026-01-01T00:00:00.000Z' },
      ];
