1|import {
2|	resolveCandidateStage,
3|	resolveStagesForTask,
4|} from '../stageResolution.js';
5|import { collectResumeEvidence } from './collectResumeEvidence.js';
6|import { resolveResumeLabel } from './resolveResumeLabel.js';
7|
8|/***
9| * MARK: autoResumeTask
10| * @description Transitions one `interrupted` task back to runnable
11| *   (`in_stage`) exactly the way manual `resumeTask` does — cleared
12| *   `wasInterrupted`, fresh auto-iteration budget, history entry, persisted
13| *   markdown — but WITHOUT dispatching execution itself. Additionally stamps
14| *   the durable `resumedAfterInterruption` marker (plus an `interruptedAt`
15| *   snapshot of the pre-flip timestamp, so oldest-interruption ordering
16| *   survives the flip) that keeps Rule 0 priority until the first dispatch
17| *   consumes it. The caller is either startup recovery (the normal
18| *   `scheduleTick` then dispatches under the busy gate) or `scheduleTick`
19| *   (which dispatches immediately after). Never calls `executeStage`
20| *   directly, so the single-active invariant holds. Idempotent: a
21| *   non-interrupted task is returned untouched. The history label names the
22| *   recovery route (see `resolveResumeLabel`): server restart for genuine
23| *   reconcile recoveries, runner interrupt (with runner id + reason) for
24| *   runner-path resumes.
25| * @param {Object} store
26| * @param {string} projectId
27| * @param {string} taskId
28| * @param {string} [projectCwd]
29| * @returns {Object|null} The task, or null when unknown.
30|  * @example autoResumeTask(store, "p1", "t1") => task (status "in_stage")
31| ***/
32|export function autoResumeTask(store, projectId, taskId, projectCwd, { reason } = {}) {
33|	const task = store.getTask(projectId, taskId);
34|	if (!task || task.status !== "interrupted") return task || null;
35|	// Snapshot BEFORE the flip: `updatedAt` is about to become "now" for
36|	// every resumed task, which would destroy oldest-first ordering.
37|	task.interruptedAt =
38|		task.updatedAt || task.enteredStageAt || new Date().toISOString();
39|	task.resumedAfterInterruption = true;
40|	task.wasInterrupted = false;
41|	task.status = "in_stage";
42|	task.updatedAt = new Date().toISOString();
43|	if (typeof store._resetAutoIteration === "function") {
44|		store._resetAutoIteration(task);
45|	}
46|	// S6: the label names the actual recovery route — server restart for
47|	// genuine reconcile recoveries, runner interrupt (with id + reason) for
48|	// runner-path resumes — instead of one string for both.
49|	const historyAction = resolveResumeLabel(task);
50|	if (typeof store._recordHistory === "function") {
51|		try {
52|			store._recordHistory(task, historyAction, task.updatedAt);
53|		} catch {
54|			// History is best-effort; the flip already happened.
55|		}
56|	}
57|	// WP6 auto-resume evidence: every resume records WHAT was discovered
58|	// (markers present, SHAs, verdict) into the timeline so an operator can
59|	// audit the decision. Best-effort: evidence gathering must never break
60|	// the flip.
61|	try {
62|		const evidence = collectResumeEvidence(store, task);
63|		let stageLabel = task.currentStageId || "stage";
64|		try {
65|			const project =
66|				typeof store.projectStore?.getProject === "function"
67|					? store.projectStore.getProject(projectId)
68|					: null;
69|			if (project) {
70|				const stages = resolveStagesForTask(project, task);
71|				const stage = resolveCandidateStage(stages, task.currentStageId);
72|				if (stage?.name || stage?.id) stageLabel = stage.name || stage.id;
73|			}
74|		} catch {
75|			// Label resolution is best-effort; the evidence still records.
76|		}
77|		if (typeof store._recordTimeline === "function") {
78|			store._recordTimeline(task, {
79|				stage: stageLabel,
80|				status: "Resumed",
81|				reason: reason || historyAction,
82|				...evidence,
83|			});
84|		}
85|	} catch {
86|		// Timeline evidence is best-effort; the flip already happened.
87|	}
88|	const cwd =
89|		typeof store._resolveProjectCwd === "function"
90|			? store._resolveProjectCwd(projectId, projectCwd)
91|			: projectCwd;
92|	if (typeof store._saveTaskMarkdown === "function") {
93|		store._saveTaskMarkdown(cwd, task);
94|	}
95|	store.eventBridge?.broadcastGlobal?.("TASK_UPDATED", task);
96|	return task;
97|}

