206|/***
207| * MARK: getBlockedState
208| * @description Single source of truth for whether a task is held up by
209| * unfinished prerequisite tasks, and which tasks those are. Prefers the
210| * scheduler's isBlocked verdict when the payload carries it so every surface
211| * agrees; otherwise derives from blockedBy plus the live task list.
212| * @example getBlockedState({ blockedBy: ['a'] }, [{ id: 'a', status: 'in_stage' }]) => { isBlocked: true, blockerIds: ['a'] }
213| * @example getBlockedState({ isBlocked: false, blockedBy: ['a'] }, [{ id: 'a', status: 'in_stage' }]) => { isBlocked: false, blockerIds: ['a'] }
214| * @param {Object} [task] - The task object (or null/undefined for safety).
215| * @param {Array<Object>} [allTasks=[]] - Live task list used to check blocker statuses.
216| * @returns {{ isBlocked: boolean, blockerIds: Array<string> }} Blocked verdict plus blocker ids.
217| ***/
218|export function getBlockedState(task, allTasks = []) {
219|  const liveTasks = Array.isArray(allTasks) ? allTasks : [];
220|  const blockedBy = Array.isArray(task?.blockedBy) ? task.blockedBy : [];
221|  const blockerIds =
222|    Array.isArray(task?.blockers) && task.blockers.length > 0 ? [...task.blockers] : [...blockedBy];
223|  if (typeof task?.isBlocked === 'boolean') {
224|    return { isBlocked: task.isBlocked, blockerIds };
225|  }
226|  const isBlocked =
227|    blockedBy.length > 0 &&
228|    liveTasks.some((t) => blockedBy.includes(t?.id) && t?.status !== 'completed');
