324|/***
325| * MARK: resolveTimelineStageLabel
326| * @description Maps a timeline stage label to a human-readable stage name for
327| *   display. Stage ids are positional numbers that can change when the
328| *   workflow is edited, so legacy timeline entries that recorded a bare
329| *   numeric id are mapped (best-effort) onto the current stage with that id.
330| *   Labels that are already human-readable names, or numeric labels that match
331| *   no current stage, are returned unchanged.
332| * @example resolveTimelineStageLabel('1', [{ id: '1', name: 'Idea' }]) => 'Idea'
333| * @example resolveTimelineStageLabel('Idea', [{ id: '1', name: 'Idea' }]) => 'Idea'
334| * @example resolveTimelineStageLabel('9', [{ id: '1', name: 'Idea' }]) => '9'
335| * @param {string} [stageLabel] - Timeline stage label (legacy numeric id or name).
336| * @param {Array<Object>} [stages=[]] - The current workflow stages.
337| * @returns {string} Display label for the timeline entry.
338| ***/
339|export function resolveTimelineStageLabel(stageLabel, stages = []) {
340|  const label =
341|    stageLabel === undefined || stageLabel === null
342|      ? ''
343|      : String(stageLabel).trim();
344|  if (!label || !/^\d+$/.test(label) || !Array.isArray(stages)) return label;
345|  const match = stages.find((s) => String(s?.id) === label);
346|  return match?.name || label;
