358|/***
359| * MARK: resolveTimelineStageRecord
360| * @description Finds the workflow stage record a stored timeline row is
361| *   headed with, matching the raw stored label against stage ids and names
362| *   (case-insensitive for names, so legacy numeric ids still match). Returns
363| *   null when no stage resolves — callers fail open (keep stored fields)
364| *   rather than destroy signal for an unknown or renamed stage.
365| * @example resolveTimelineStageRecord([{ id: '2', name: 'Review Plan', type: 'human' }], 'Review Plan') => { id: '2', name: 'Review Plan', type: 'human' }
366| * @example resolveTimelineStageRecord([{ id: '2', name: 'Review Plan', type: 'human' }], '2') => { id: '2', name: 'Review Plan', type: 'human' }
367| * @example resolveTimelineStageRecord([], 'Review Plan') => null
368| * @param {Array<Object>} [stages=[]] - The current workflow stages.
369| * @param {*} [label] - Raw stored timeline stage label.
370| * @returns {Object|null} The matching stage record, or null when unresolved.
371| ***/
372|function resolveTimelineStageRecord(stages, label) {
373|  if (!Array.isArray(stages) || label === undefined || label === null) return null;
374|  const raw = String(label).trim();
375|  if (!raw) return null;
376|  const lowered = raw.toLowerCase();
377|  for (const candidate of stages) {
378|    if (!candidate || typeof candidate !== 'object') continue;
379|    if (
380|      candidate.id !== undefined &&
381|      candidate.id !== null &&
382|      String(candidate.id).trim() === raw
383|    ) {
384|      return candidate;
385|    }
386|    if (
387|      typeof candidate.name === 'string' &&
388|      candidate.name.trim().toLowerCase() === lowered
389|    ) {
390|      return candidate;
391|    }
392|  }
393|  return null;
